steps.code:
// Acquisition
window.op('track', 'signup_started', { source: 'pricing_page' });
window.op('track', 'signup_completed', { plan: 'free', source: 'pricing_page' });

// Activation: the steps a user must finish to get value
window.op('track', 'workspace_created', { seats: 1 });
window.op('track', 'data_imported', { rows: 240, method: 'csv' });
window.op('track', 'first_report_created', { template: 'retention' });

// Expansion and churn signals
window.op('track', 'teammate_invited', { invited_count: 3 });
window.op('track', 'plan_upgraded', { from: 'free', to: 'pro' });

// After a successful login or signup
window.op('identify', {
  profileId: user.id,
  firstName: user.firstName,
  lastName: user.lastName,
  email: user.email,
  properties: {
    plan: 'free',
    signup_month: '2026-03',
  },
});

// On logout
window.op('clear');
